import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import { ClerkProvider, SignIn, SignUp, SignedIn, SignedOut, UserButton, useUser } from '@clerk/clerk-react';
import { AppBar, Toolbar, Typography, Button, Container } from '@mui/material';

const clerkFrontendApi = process.env.REACT_APP_CLERK_FRONTEND_API; // Store in .env

// Home Page Component
function Home() {
  return (
    <Container maxWidth="md" sx={{ mt: 4 }}>
      <Typography variant="h4" gutterBottom>Welcome to the Malware Analysis App</Typography>
      <SignedOut>
        <Typography variant="h6" color="error">You must be signed in to access features.</Typography>
        <Link to="/sign-in">
          <Button variant="contained" color="primary">Sign In</Button>
        </Link>
      </SignedOut>
      <SignedIn>
        <Typography variant="h6" color="success">You are signed in! 🎉</Typography>
        <UserButton />
        <Link to="/dashboard">
          <Button variant="contained" color="secondary" sx={{ ml: 2 }}>Go to Dashboard</Button>
        </Link>
      </SignedIn>
    </Container>
  );
}

// Dashboard (Protected Route)
function Dashboard() {
  const { user } = useUser();
  return (
    <Container maxWidth="md" sx={{ mt: 4 }}>
      <Typography variant="h4">Dashboard</Typography>
      <Typography variant="h6">Welcome, {user?.fullName}!</Typography>
      <img src={user?.profileImageUrl} alt="Profile" width={50} style={{ borderRadius: '50%' }} />
      <Typography variant="body1">Email: {user?.primaryEmailAddress?.emailAddress}</Typography>
    </Container>
  );
}

// Main App Component
function App() {
  return (
    <ClerkProvider frontendApi={clerkFrontendApi}>
      <Router>
        {/* Navbar */}
        <AppBar position="static">
          <Toolbar>
            <Typography variant="h6" sx={{ flexGrow: 1 }}>
              <Link to="/" style={{ textDecoration: 'none', color: 'white' }}>Malware Analysis</Link>
            </Typography>
            <UserButton />
          </Toolbar>
        </AppBar>

        {/* Routes */}
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/sign-in" element={<SignIn />} />
          <Route path="/sign-up" element={<SignUp />} />
          <Route path="/dashboard" element={
            <SignedIn>
              <Dashboard />
            </SignedIn>
          } />
        </Routes>
      </Router>
    </ClerkProvider>
  );
}

export default App;
